mapper.select:
SELECT id, user_id, record_date, meal_type, create_time, update_time, delete_flag
FROM diet_record
WHERE user_id = #{userId}
  AND record_date = #{date}
  AND delete_flag = 0
ORDER BY meal_type

SELECT id, user_id, record_date, meal_type, create_time, update_time, delete_flag
FROM diet_record
WHERE user_id = #{userId}
  AND record_date BETWEEN #{startDate} AND #{endDate}
  AND delete_flag = 0
ORDER BY record_date, meal_type
